                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x, color))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    top = min(y for comp in comps for y, _, _ in comp)
    out = [[0] * w for _ in range(h)]
    for comp in comps:
        dy = top - min(y for y, _, _ in comp)
        for y, x, color in comp:
            out[y + dy][x] = color
    return out
